def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [a for _, a in history]
    own = [a for a, _ in history]

    def count(seq, ch):
        c = 0
        for x in seq:
            if x == ch:
                c += 1
        return c

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    my_def = count(own, 'D')
    op_def = count(opp, 'D')
    op_c = n - op_def

    if n < 6:
        return 'C'

    last_op = opp[-1]
    last_own = own[-1]
    op_d_streak = streak(opp, 'D')
    my_d_streak = streak(own, 'D')

    # Strong retaliation against sustained defection, with limited forgiveness.
    if op_d_streak >= 2:
        if op_d_streak >= 5:
            return 'D'
        if last_own == 'D':
            if op_d_streak >= 3:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    if last_op == 'D':
        return 'D'

    remaining = 100 - n
    op_rate = op_def / float(n)

    # If opponent is mostly cooperative, cooperate but occasionally exploit near end.
    if op_rate < 0.12:
        if remaining <= 1:
            if remaining == 0:
                return 'D'
            return 'D'
        if op_d_streak == 0 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Against moderately exploitative opponents, test occasionally.
    if op_rate < 0.35:
        if op_d_streak == 0 and my_d_streak == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Against highly defective opponents, defect often to avoid being exploited.
    if op_rate >= 0.75:
        return 'D'

    if last_op == 'C':
        if op_d_streak == 0 and rng.random() < 0.15:
            return 'C'
        return 'D'

    return 'D'

